#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    const string target = "ACTG";
    int answer = INT_MAX;

    for (int i = 0; i + 3 < n; ++i) {
        int cost = 0;

        for (int j = 0; j < 4; ++j) {
            int difference = abs(s[i + j] - target[j]);
            cost += min(difference, 26 - difference);
        }

        answer = min(answer, cost);
    }

    cout << answer << '\n';
    return 0;
}

